sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var r = new sn_ws.RESTMessageV2('x_1761730_ats.Resume Ranking', 'Get Resume Ranking');

    // var attachmentGR = new GlideRecord('sys_attachment');
    // attachmentGR.setLimit(10);
    // attachmentGR.addQuery('table_name', current.getTableName()); // Change to your table
    // attachmentGR.addQuery('table_sys_id', current.getUniqueValue()); // Sys ID of the record
    // attachmentGR.query();
    // var fileContent = "";
    // if (attachmentGR.next()) {
    var attachment = new GlideSysAttachment();
    var agr = attachment.getAttachments(current.getTableName(), current.getUniqueValue());
	var attachmentContent = "";
    while (agr.next()) {
        gs.info(agr.getValue('file_name'));
        gs.info("content type");
        gs.info(agr.getValue('content_type'));
        attachmentContent = attachment.getContent(agr);
        gs.info(attachmentContent);
    }

    var messages = [
        {
            "role": "system",
            "content": "You are a resume extractor.Extract the required information from the resume content and present the following details in structured JSON format"
        },
		{
			"role": "user",
			"content": attachmentContent
		}
    ];
    payload = {
        'model': "sonar-pro",
        'messages': messages,
        'temperature': 0.7
    };


    try {
        var r = new sn_ws.RESTMessageV2('x_1761730_ats.Resume Ranking', 'Get Resume Ranking');
        r.setRequestBody(JSON.stringify(payload));
        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        if (httpStatus === 200) {
            var jsonResponseBody = JSON.parse(responseBody);
            if (jsonResponseBody["choices"] && jsonResponseBody["choices"].length > 0) {
                var responseContent = jsonResponseBody["choices"][0]['message']['content'];
				gs.info(responseContent);
				// current.extracted_resume_details.test2 = {'testing': 123};
				current.extracted_resume_details = responseContent;
                // current.resume_ranking = responseContent["score"] || 0;
                // current.resume_ranking_summary = responseContent["explanation"] || "";
                current.update();
            }
        }
    } catch (ex) {
        var message = ex.message;
        gs.error(message);
    }

})(current, previous);
